    explanation:
      "Burn rate = current error rate / budgeted error rate. For a 99.9% SLO, the budget is 0.001 (0.1%). An actual error rate of 0.01 (1%) gives burn rate = 0.01 / 0.001 = 10. At 10×, you exhaust the 30-day budget in about 3 days.",
