      "Stack overflow: the stack grew past the end of the BSS region upward and the CPU tried to execute BSS contents as code; or — more commonly — the overflowed stack corrupted BSS variables and the code later dereferenced one of those corrupted values as a pointer, jumping to a garbage address in the BSS range",
      "The CPU is defective",
