      "FreeRTOS tickless idle is enabled. A task is blocked for 500 ms with vTaskDelay. The vPortSuppressTicksAndSleep implementation enters Stop mode and wakes via RTC alarm. After waking, the implementation calls vTaskStepTick(498) instead of vTaskStepTick(500) due to a measurement error. What happens to the task?",
    options: [
      "Nothing — FreeRTOS corrects the error automatically",
      "The task wakes 2 ms late. vTaskStepTick advances the FreeRTOS tick counter by 498; the task was waiting for 500 ticks to elapse. With only 498 elapsed, FreeRTOS thinks 2 ticks remain before the task should wake. SysTick resumes and fires 2 more ticks (2 ms) before FreeRTOS unblocks the task. The task was supposed to wake at t=500; it actually wakes at t=502. For soft-real-time tasks this is harmless; for tasks with tight timing requirements, accurate vTaskStepTick correction is important.",
      "The task never wakes",
      "FreeRTOS crashes — vTaskStepTick with wrong argument corrupts the kernel",
    ],
    correct: 1,
    explanation:
      "vTaskStepTick tells FreeRTOS how many ticks elapsed during sleep. An undercount means FreeRTOS thinks less time passed than actually did — tasks that were scheduled to wake during that period are delayed by the undercount amount. An overcount is more dangerous: FreeRTOS thinks more time passed than did, and may unblock tasks early (before their delay has elapsed). For most applications, a 1-2 tick error is acceptable. Safety-critical or hard-real-time tasks may need more precise elapsed-time measurement (e.g., using the RTC subsecond register for sub-tick accuracy).",
    difficulty: "medium",
    tags: ["lesson-checkpoint"],
    sourceLesson: "10/10-9/04",
