    type: "multiple-choice",
    question: "Why does UVM separate driver from monitor when they touch the same interface?",
    options: [
      "Historical accident",
      "Driver and monitor have fundamentally different responsibilities: driver ACTIVELY DRIVES the interface (writes signals), monitor PASSIVELY OBSERVES (only reads). Separation gives: (1) the monitor can be reused as a checking-only component in passive agents that just observe; (2) the monitor sees what actually happened on the bus, including outputs the driver doesn't generate (e.g., the DUT's response); (3) for some agents both directions need monitoring — driver-only or monitor-only configurations cover the patterns cleanly. The separation maps to the producer/consumer asymmetry of the protocol.",
      "They can't share an interface",
      "The factory requires separation",
    ],
    correct: 1,
    explanation:
      "Driver and monitor have asymmetric roles. The driver injects stimulus; the monitor observes ground truth. The monitor's job includes seeing the DUT's responses (which the driver doesn't generate) and verifying protocol compliance independently of how the driver thinks it sent stimulus. Passive agents (monitor only, no driver) reuse the monitor for system-level checking. The separation is a deliberate methodology choice that maps to verification's producer/consumer asymmetry.",
    difficulty: "medium",
    tags: ["lesson-checkpoint"],
    sourceLesson: "11/11-2/01",
