    question:
      "A verification engineer wants to debug a rare race condition in an emulation run. She sets up a trace buffer capturing 16 signals at 8,192 cycles depth, triggers on a specific state combination, and runs the test. The race condition does not appear in the captured window. What are her two most likely options?",
    options: [
      "Switch to simulation for this debug; emulation has fundamentally inadequate observability for any bug.",
      "Increase the trace buffer depth (if FPGA resources permit) or add a more specific trigger condition that fires closer to the actual failure, so the bug falls within the capture window. Alternatively, add intermediate assertions in the RTL that narrow where the race occurs, compile a new bitfile, and re-run.",
      "The bug does not exist; if it were real, the 8,192-cycle window would always capture it.",
      "Increase clock frequency on the emulator to make the race condition more deterministic.",
    ],
    correct: 1,
    explanation:
      "When a bug does not fall within the trace buffer window, the two main approaches are: (1) increase trace depth if FPGA block RAM resources are available — more depth means a longer capture window; (2) refine the trigger condition to fire closer in time to the failure, so the relevant cycles fall within the fixed-depth window. Both require recompiling the bitfile, which takes time. A third approach is to add RTL assertions that subdivide the problem space, compile a new bitfile, and use the assertion to fire a more specific trigger. Switching to simulation is a valid last resort but loses emulation's speed advantage for a rare race that may require millions of cycles to reproduce.",
    difficulty: "medium",
    tags: ["lesson-checkpoint"],
    sourceLesson: "11/11-10/01",
