    explanation:
      "ICE mode creates a fundamental clock frequency mismatch: the emulation runs at 1–5 MHz but the physical hardware operates in real wall-clock time. The emulated design needs hundreds of times more wall-clock time than the ASIC would to execute the same number of training cycles, so wall-clock deadlines enforced by the physical device — like the SSD's 500 ms training window — expire long before the emulated design finishes responding. Solutions include protocol stubs, vendor-supplied speed adapters (speed bridges) that buffer between real-time I/O and the slow emulated design, or protocol emulators in place of the real device. This is the primary constraint that makes ICE mode for high-speed serial interfaces non-trivial.",
    difficulty: "medium",
    tags: ["lesson-checkpoint"],
