      "Cp = (10.050 − 9.950) / (6 × 0.012) = 0.100 / 0.072 = 1.39. Cpk = min( (10.050 − 10.010)/(3 × 0.012), (10.010 − 9.950)/(3 × 0.012) ) = min( 0.040/0.036, 0.060/0.036 ) = min(1.11, 1.67) = 1.11. Cpk < Cp because the process is shifted above center (X̄̄ = 10.010 vs target 10.000). The minimum of the two Cpk halves is 1.11 — the USL-facing half — indicating the process is encroaching on the upper spec. Re-centering on 10.000mm would bring Cpk ≈ Cp ≈ 1.39.",
