    moduleId: "14-4",
    type: "multiple-choice",
    question: "What is the structural difference between Jidoka and automation?",
    options: [
      "Jidoka and automation are the same thing in modern usage",
      "Jidoka is 'autonomation' — automation that detects abnormalities and stops, allowing human intervention to address root cause; pure automation runs through abnormalities and produces defective output until a human notices; Jidoka builds quality in at the source, automation does not",
      "Automation replaces operators; Jidoka adds operators",
      "Jidoka requires Japanese cultural context; automation is universal",
    ],
    correct: 1,
    explanation:
      "Jidoka (sometimes glossed as 'autonomation') is the design pattern where the machine itself detects an abnormality and stops, signaling for human help. The human addresses the root cause; the process resumes only when the cause is corrected. Pure automation runs through abnormalities and produces defective output until detected downstream. The pillar is build-in-quality-at-the-source; that requires the stop-and-signal pattern. The Japanese origin is historical; the principle is universal — every modern factory automation system that does in-line quality checks and stops the line is implementing Jidoka, by whatever name.",
    difficulty: "medium",
    tags: ["lesson-checkpoint"],
